export const ENTITY_SCHEMAS: Record<string, EntitySchema> = Object.fromEntries(
  RAW.map((s) => [s.name, s]),
);

export const ENTITY_NAMES: string[] = Object.keys(ENTITY_SCHEMAS);

export function getEntitySchema(name: string): EntitySchema | undefined {
  return ENTITY_SCHEMAS[name];
}
